import itertools, sys
sys.path.insert(0, "src")
from accountability.authorization import patterns_intersect, intersection_pattern, pattern_matches

# brute-force intersection over all strings up to length 6 on alphabet {a,b}
strings = ["".join(t) for n in range(7) for t in itertools.product("ab", repeat=n)]
def brute(p, q):
    return any(pattern_matches(p, s) and pattern_matches(q, s) for s in strings)

atoms = ["a", "b", "*", "aa", "ab", ""]
patterns = set()
for n in range(1, 4):
    for combo in itertools.product(atoms, repeat=n):
        p = "".join(combo)
        if 4 <= len(p) <= 6 and "*" in p.replace("**","*"):
            patterns.add(p)
patterns = sorted(patterns)
bad = 0
for p, q in itertools.product(patterns, repeat=2):
    expected = brute(p, q)
    got = patterns_intersect(p, q)
    if got != expected:
        # brute force bounded at length 6 may miss long witnesses; check bounded mismatch only when expected True
        if expected:
            print("MISS:", p, q); bad += 1
        else:
            # got True but no short witness: verify with longer bound
            long_strings = ["".join(t) for n in range(7, 11) for t in itertools.product("ab", repeat=n)]
            if not any(pattern_matches(p, s) and pattern_matches(q, s) for s in long_strings):
                print("FALSE POSITIVE:", p, q); bad += 1
    # soundness of intersection_pattern: merge matches => both match
    ip = intersection_pattern(p, q)
    if ip is not None:
        for s in strings:
            if pattern_matches(ip, s) and not (pattern_matches(p, s) and pattern_matches(q, s)):
                print("UNSOUND MERGE:", p, q, ip, s); bad += 1
        if not got:
            print("MERGE WITHOUT INTERSECTION:", p, q); bad += 1
    elif got:
        print("INTERSECTION WITHOUT MERGE:", p, q); bad += 1
print("patterns:", len(patterns), "pairs:", len(patterns)**2, "bad:", bad)
